package local.skyfamily;
import android.content.*;import android.graphics.*;import android.os.SystemClock;import java.net.*;import java.io.*;import java.util.*;import org.json.*;
final class UploadReceiver {
 final ServerSocket server;final InetAddress address;final String secret=UUID.randomUUID().toString().replace("-","");final File folder;final Runnable uploaded;final Context context;final long expires=SystemClock.elapsedRealtime()+900000L;volatile boolean open=true;volatile Socket active;
 UploadReceiver(InetAddress ip,File dir,Runnable callback)throws Exception{this(null,ip,dir,callback);}
 UploadReceiver(Context c,InetAddress ip,File dir,Runnable callback)throws Exception{context=c==null?null:c.getApplicationContext();address=ip;folder=dir;uploaded=callback;if(!folder.exists()&&!folder.mkdirs())throw new IOException("Cannot create upload folder");server=new ServerSocket();server.bind(new InetSocketAddress(ip,0));server.setSoTimeout(1500);Thread thread=new Thread(()->run(),"sky-local-upload");thread.setDaemon(true);thread.start();}
 String url(){return "http://"+address.getHostAddress()+":"+server.getLocalPort()+"/"+secret;}
 void close(){open=false;try{server.close();}catch(Exception ignored){}Socket current=active;if(current!=null)try{current.close();}catch(Exception ignored){}}
 void run(){while(open&&SystemClock.elapsedRealtime()<expires)try{Socket socket=server.accept();active=socket;socket.setSoTimeout(20000);try{serve(socket);}finally{active=null;socket.close();}}catch(SocketTimeoutException ignored){}catch(Exception ignored){}close();}
 String line(InputStream in)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();for(int i=0;i<4096;i++){int c=in.read();if(c<0)throw new EOFException();if(c==10)return b.toString("US-ASCII").replace("\r","");b.write(c);}throw new IOException("Header limit");}
 void reply(Socket s,int status,String type,String body)throws Exception{byte[] data=body.getBytes("UTF-8");String header="HTTP/1.1 "+status+(status==200?" OK":" Rejected")+"\r\nContent-Type: "+type+"; charset=utf-8\r\nContent-Length: "+data.length+"\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\nX-Frame-Options: DENY\r\nConnection: close\r\n\r\n";s.getOutputStream().write(header.getBytes("US-ASCII"));s.getOutputStream().write(data);s.getOutputStream().flush();}
 String html(){return "<!doctype html><meta name='viewport' content='width=device-width,initial-scale=1'><title>Sky Family Upload</title><style>body{font:18px sans-serif;background:#10192a;color:#edf5ff;max-width:620px;margin:30px auto;padding:24px}input,button{font:inherit;padding:14px;margin:12px 0}button{background:#a9d8ca;border:0;border-radius:14px}progress{width:100%}</style><h1>Send to your frame</h1><p>Trusted LAN only. HTTP is unencrypted. Images: 10 MiB / 20 MP. Books: EPUB, PDF or UTF-8 TXT, up to 50 MiB (TXT 8 MB). Files are stored only on your frame. Use trusted PDFs/books.</p><input id='files' type='file' accept='image/*,.epub,.pdf,.txt,application/epub+zip,application/pdf,text/plain' multiple><button id='send'>Upload files</button><progress id='bar' max='100' value='0'></progress><ul id='status'></ul><script>var picker=document.getElementById('files'),button=document.getElementById('send'),status=document.getElementById('status');function say(t){var item=document.createElement('li');item.textContent=t;status.appendChild(item);}button.onclick=function(){var list=picker.files,i=0;button.disabled=true;function next(){if(i>=list.length){say('Finished');button.disabled=false;return;}var file=list[i++];if(file.size>52428800){say(file.name+': too large');next();return;}var x=new XMLHttpRequest();x.open('POST',location.pathname+'/upload');x.setRequestHeader('X-Sky-Upload','"+secret+"');x.setRequestHeader('X-Sky-Name',encodeURIComponent(file.name));x.setRequestHeader('Content-Type',file.type||'application/octet-stream');x.upload.onprogress=function(e){if(e.lengthComputable)document.getElementById('bar').value=100*e.loaded/e.total;};x.onload=function(){say(file.name+': '+x.responseText);next();};x.onerror=function(){say('Connection failed; keep the frame upload screen open');button.disabled=false;};x.send(file);}next();};</script>";}
 void serve(Socket socket)throws Exception{InputStream in=socket.getInputStream();String[] request=line(in).split(" ");if(request.length!=3)return;HashMap<String,String> headers=new HashMap<>();int total=0;while(true){String h=line(in);total+=h.length();if(total>16384)return;if(h.isEmpty())break;int colon=h.indexOf(':');if(colon<1)return;String key=h.substring(0,colon).trim().toLowerCase(Locale.US);if(headers.containsKey(key))return;headers.put(key,h.substring(colon+1).trim());}String route="/"+secret;if(!open||SystemClock.elapsedRealtime()>=expires){reply(socket,403,"text/plain","Session closed");return;}if(request[0].equals("GET")&&request[1].equals(route)){reply(socket,200,"text/html",html());return;}if(!request[0].equals("POST")||!request[1].equals(route+"/upload")||!secret.equals(headers.get("x-sky-upload"))||headers.containsKey("transfer-encoding")){reply(socket,403,"text/plain","Not allowed");return;}long length;try{length=Long.parseLong(headers.get("content-length"));}catch(Exception e){reply(socket,411,"text/plain","Content length required");return;}if(length<=0||length>52428800L){reply(socket,413,"text/plain","Maximum file size is 50 MiB");return;}String filename="Uploaded file";try{filename=URLDecoder.decode(headers.containsKey("x-sky-name")?headers.get("x-sky-name"):filename,"UTF-8");}catch(Exception ignored){}filename=filename.substring(0,Math.min(filename.length(),200));File temp=File.createTempFile("incoming-",".part",folder);File target=null;File coverFile=null;boolean saved=false;try{try(OutputStream out=new FileOutputStream(temp)){byte[] b=new byte[16384];long remaining=length;while(remaining>0){if(!open||SystemClock.elapsedRealtime()>=expires)throw new IOException("Session closed");int n=in.read(b,0,(int)Math.min(b.length,remaining));if(n<0)throw new EOFException();out.write(b,0,n);remaining-=n;}}byte[] magic=new byte[5];try(InputStream head=new FileInputStream(temp)){head.read(magic);}boolean pdf=magic[0]=='%'&&magic[1]=='P'&&magic[2]=='D'&&magic[3]=='F'&&magic[4]=='-';boolean epub=magic[0]=='P'&&magic[1]=='K';boolean text=filename.toLowerCase(Locale.US).endsWith(".txt")||"text/plain".equals(headers.get("content-type"));if(pdf||epub||text){if(context==null){reply(socket,415,"text/plain","Use the ebook-enabled QR screen");return;}File books=new File(context.getFilesDir(),"books");books.mkdirs();long used=0;File[] all=books.listFiles();if(all!=null)for(File file:all)used+=file.length();android.content.SharedPreferences prefs=context.getSharedPreferences("sky",0);JSONArray index=new JSONArray(prefs.getString("books.index","[]"));if(index.length()>=100||used+length>250000000L)throw new IOException("Bookshelf storage limit reached");String id=UUID.randomUUID().toString(),extension=pdf?".pdf":epub?".epub":".txt";target=new File(books,id+extension);if(!temp.renameTo(target))throw new IOException("Cannot store book");String title=filename.lastIndexOf('.')>0?filename.substring(0,filename.lastIndexOf('.')):filename,author="";int pages=0;Bitmap cover=null;if(pdf){PdfPages.Page page=PdfPages.render(context,target,0,240,320);cover=page.image;pages=page.count;if(!page.title.trim().isEmpty())title=page.title;author=page.author;}else{if(text&&!epub){byte[] data=BookData.read(new FileInputStream(target),8000000);java.nio.charset.Charset.forName("UTF-8").newDecoder().onMalformedInput(java.nio.charset.CodingErrorAction.REPORT).onUnmappableCharacter(java.nio.charset.CodingErrorAction.REPORT).decode(java.nio.ByteBuffer.wrap(data));}BookData book=BookData.load(target);if(!book.title.equals("Book"))title=book.title;author=book.author;if(book.cover!=null){BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(book.cover,0,book.cover.length,options);options.inSampleSize=1;while(options.outWidth/options.inSampleSize>240||options.outHeight/options.inSampleSize>320)options.inSampleSize*=2;options.inJustDecodeBounds=false;cover=BitmapFactory.decodeByteArray(book.cover,0,book.cover.length,options);}}if(cover!=null){coverFile=new File(books,id+".png");try(OutputStream out=new FileOutputStream(coverFile)){cover.compress(Bitmap.CompressFormat.PNG,100,out);}cover.recycle();}JSONObject record=new JSONObject().put("id",id).put("file",target.getName()).put("title",title).put("author",author).put("format",pdf?"PDF":epub?"EPUB":"TXT");if(pdf)record.put("pages",pages);index.put(record);if(!prefs.edit().putString("books.index",index.toString()).commit())throw new IOException("Could not save bookshelf index");saved=true;reply(socket,200,"text/plain","Imported into Bookshelf");uploaded.run();return;}if(length>10485760L)throw new IOException("Images must be at most 10 MiB");BitmapFactory.Options dimensions=new BitmapFactory.Options();dimensions.inJustDecodeBounds=true;BitmapFactory.decodeFile(temp.getPath(),dimensions);if(dimensions.outWidth<1||dimensions.outHeight<1||dimensions.outWidth>8000||dimensions.outHeight>8000||(long)dimensions.outWidth*dimensions.outHeight>20000000L)throw new IOException("Unsupported image or above 20 MP limit");long used=0;int count=0;File[] images=folder.listFiles((d,name)->name.endsWith(".image"));if(images!=null)for(File image:images){used+=image.length();count++;}if(count>=50||used+length>104857600L)throw new IOException("Image gallery quota reached");target=new File(folder,"image-"+System.currentTimeMillis()+"-"+UUID.randomUUID().toString().substring(0,8)+".image");if(!temp.renameTo(target))throw new IOException("Cannot store image");saved=true;reply(socket,200,"text/plain","Saved in Uploaded images");uploaded.run();}catch(Exception e){reply(socket,415,"text/plain","Import failed: "+e.getMessage());}finally{temp.delete();if(!saved){if(target!=null)target.delete();if(coverFile!=null)coverFile.delete();}}}
}
